import type { WorkspaceAgent } from "#/api/typesGenerated";

/**
 * Canonical messages for startup and shutdown script issues.
 * Used by the per-agent-row tooltips in AgentStatus; the
 * start-related entries are also shared with per-agent health
 * classification in getAgentScriptIssues.
 */
export const agentScriptMessages = {
	start_error: {
		title: "Startup script failed",
		detail:
			"A startup script exited with an error. Check the agent logs for details.",
	},
	start_timeout: {
		title: "Startup script is taking longer than expected",
		detail:
			"A startup script has exceeded the expected time. Check the agent logs for details.",
	},
	shutdown_error: {
		title: "Shutdown script failed",
		detail:
			"A shutdown script exited with an error. Check the agent logs for details.",
	},
	shutdown_timeout: {
		title: "Shutdown script is taking longer than expected",
		detail:
			"A shutdown script has exceeded the expected time. Check the agent logs for details.",
	},
} as const;

/**
 * Canonical messages for agent connection issues (the agent
 * process connecting to the Optimus IDE Collab control plane).
 */
export const agentConnectionMessages = {
	connecting: {
		title: "Workspace agent is connecting",
		detail:
			"The workspace agent has not connected yet. Wait for it to connect or check the logs if it does not.",
	},
	timeout: {
		title: "Agent is taking longer than expected to connect",
		detail:
			"Continue to wait and check the log output for errors. If agents do not connect, try restarting the workspace.",
	},
	disconnected: {
		title: "Workspace agent has disconnected",
		detail:
			"Check the log output for errors. If agents do not reconnect, try restarting the workspace.",
	},
} as const;

interface AgentHealthIssue {
	title: string;
	detail: string;
	severity: "info" | "warning";
	// Whether the alert should be visually prominent. Usually true for
	// warnings, but connection timeout and startup timeout are
	// exceptions (warning severity without prominent styling).
	prominent: boolean;
}

/**
 * Classifies connectivity-related health issues for an individual agent.
 * These issues affect the agent panel border color and warning visibility.
 * Script failures are excluded from this function to prevent them from
 * incorrectly suggesting agent connectivity problems.
 */
export function getAgentConnectivityIssues(
	agent: WorkspaceAgent,
): AgentHealthIssue[] {
	const issues: AgentHealthIssue[] = [];

	if (agent.status === "disconnected") {
		issues.push({
			title: agentConnectionMessages.disconnected.title,
			detail: agentConnectionMessages.disconnected.detail,
			severity: "warning",
			prominent: false,
		});
	}

	if (agent.status === "timeout") {
		issues.push({
			title: agentConnectionMessages.timeout.title,
			detail: agentConnectionMessages.timeout.detail,
			severity: "warning",
			prominent: false,
		});
	}

	// Shutdown lifecycle states are treated as connectivity concerns rather than
	// script concerns because the workspace is actively becoming unavailable;
	// unlike startup script failures, the agent is no longer reachable once
	// shutdown begins.
	if (
		agent.lifecycle_state === "shutting_down" ||
		agent.lifecycle_state === "shutdown_error" ||
		agent.lifecycle_state === "shutdown_timeout"
	) {
		issues.push({
			title: "Workspace agent is shutting down",
			detail: "The workspace is not available while agents shut down.",
			severity: "info",
			prominent: false,
		});
	}

	if (agent.status === "connecting") {
		issues.push({
			title: agentConnectionMessages.connecting.title,
			detail: agentConnectionMessages.connecting.detail,
			severity: "info",
			prominent: false,
		});
	}

	return issues;
}

/**
 * Classifies script-related health issues for an individual agent.
 * These issues are shown only in the script tabs, not in the agent panel header.
 */
export function getAgentScriptIssues(
	agent: WorkspaceAgent,
): AgentHealthIssue[] {
	const issues: AgentHealthIssue[] = [];

	// Check for script failures directly from the scripts array.
	for (const script of agent.scripts) {
		switch (script.status) {
			case "timed_out":
				issues.push({
					title: `"${script.display_name}" is taking longer than expected`,
					detail: `"${script.display_name}" has exceeded the expected time. Check the agent logs for details.`,
					severity: "warning",
					prominent: false,
				});
				break;
			case "exit_failure":
				if (script.exit_code) {
					issues.push({
						title: `"${script.display_name}" failed`,
						detail: `"${script.display_name}" exited with ${script.exit_code}. Check the agent logs for details.`,
						severity: "warning",
						prominent: false,
					});
				} else {
					issues.push({
						title: `"${script.display_name}" failed`,
						detail: `"${script.display_name}" has exited with an error. Check the agent logs for details.`,
						severity: "warning",
						prominent: false,
					});
				}
				break;
			case "pipes_left_open":
				issues.push({
					title: `"${script.display_name}" left pipes open`,
					detail: "Check the agent logs for details.",
					severity: "warning",
					prominent: false,
				});
				break;
		}
	}

	return issues;
}

/**
 * Classifies all health issues for an individual agent, combining both
 * connectivity and script issues.
 */
export function getAgentHealthIssues(
	agent: WorkspaceAgent,
): AgentHealthIssue[] {
	return [...getAgentConnectivityIssues(agent), ...getAgentScriptIssues(agent)];
}
